      (() => {
        const root=document.getElementById('tv'); if(!root||root.dataset.bound)return;root.dataset.bound='1';
        const player=document.getElementById('tv-player'),title=document.getElementById('tv-now-title'),fallback=document.getElementById('tv-official-fallback'),officialLink=document.getElementById('tv-official-link');
        root.querySelectorAll('.tv-channel').forEach(b=>b.addEventListener('click',()=>{delete player.dataset.initialSrc;
          root.querySelectorAll('.tv-channel').forEach(x=>x.classList.remove('active'));b.classList.add('active');title.textContent=b.dataset.title;
          fallback.style.display='none';
          if(b.dataset.official){player.src=b.dataset.official;fallback.style.display='block';officialLink.href=b.dataset.official;return;}
          if(b.dataset.external){player.src='about:blank';fallback.style.display='block';officialLink.href=b.dataset.external;officialLink.textContent='فتح البث الرسمي ↗';return;}
          player.src='https://www.youtube.com/embed/live_stream?channel='+encodeURIComponent(b.dataset.video)+'&autoplay=1&mute=1&rel=0';
        }));
      })();
      
