async function sbVisitCountry(){try{const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),1800);try{const r=await fetch("/api/visitor-country",{cache:"no-store",signal:ctrl.signal});if(!r.ok)return null;const d=await r.json();return typeof d.country==="string"&&/^[A-Z]{2}$/.test(d.country)?d.country:null}finally{clearTimeout(timer)}}catch{return null}}
window.sbTrackEvent=async function(eventType,itemKey){
 if(!["view","download","visit"].includes(eventType))return;
 try{const country=eventType==="visit"?await sbVisitCountry():null;const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),10000);try{const response=await fetch("https://fsctbkyzgckbuxejiaxe.supabase.co/functions/v1/track-event",{method:"POST",headers:{"Content-Type":"application/json","apikey":"sb_publishable_XpTnggE5lZfaG334Il-eIg_utGn32dI"},body:JSON.stringify({event_type:eventType,item_key:String(itemKey||"site").slice(0,120),country_code:country}),signal:ctrl.signal,keepalive:true});if(!response.ok)return false;return (await response.json())?.accepted===true;}finally{clearTimeout(timer)}}
 catch(err){console.warn("SAUDI BYTE analytics unavailable");return false;}
};
const SK="sg_stats_v3";
let sbStatsFallback=Object.create(null);
function sbCleanStats(raw){const clean=Object.create(null);if(!raw||typeof raw!=="object"||Array.isArray(raw))return clean;for(const [key,value] of Object.entries(raw)){if(["__proto__","constructor","prototype"].includes(key)||key.length>120)continue;if(key==="_sv"){if(Number.isSafeInteger(value)&&value>=0)clean[key]=value;continue}if(!value||typeof value!=="object"||Array.isArray(value))continue;const row=Object.create(null);for(const k of ["views","downs","likes"]){if(Number.isSafeInteger(value[k])&&value[k]>=0)row[k]=value[k]}row.liked=value.liked===true;clean[key]=row}return clean}
function loadS(){try{const raw=localStorage.getItem(SK);if(raw!==null)sbStatsFallback=sbCleanStats(JSON.parse(raw))}catch{}return sbStatsFallback}
function saveS(d){sbStatsFallback=sbCleanStats(d);try{localStorage.setItem(SK,JSON.stringify(sbStatsFallback))}catch{}}
function getS(id,b){const s=loadS()[id]||{};return{views:(b.bv||0)+(s.views||0),downs:(b.bd||0)+(s.downs||0),likes:(b.bl||0)+(s.likes||0),liked:!!s.liked}}
function bump(id,f,a=1){const st=loadS();if(!st[id])st[id]={};st[id][f]=(st[id][f]||0)+a;saveS(st);if(f==="views"&&window.sbTrackEvent)window.sbTrackEvent("view",id);if(f==="downs"&&window.sbTrackEvent)window.sbTrackEvent("download",id);updG()}
function togLike(id){const st=loadS();if(!st[id])st[id]={};if(st[id].liked){st[id].liked=false;st[id].likes=Math.max(0,(st[id].likes||0)-1)}else{st[id].liked=true;st[id].likes=(st[id].likes||0)+1}saveS(st);updG();return st[id].liked}
function fmt(n){if(n>=1e6)return(n/1e6).toFixed(1)+"M";if(n>=1e3)return(n/1e3).toFixed(1)+"K";return String(n)}
function updG(){let v=0,d=0,l=0;[...apps,...movies,...themes,...modsList].forEach(a=>{const s=getS(a.id,a);v+=s.views;d+=s.downs;l+=s.likes});const st=loadS();v+=(st._sv||0);document.getElementById("gV").textContent=fmt(v);document.getElementById("gD").textContent=fmt(d);document.getElementById("gL").textContent=fmt(l)}
