let gamesStart=0,gamesTotal=0,gamesBusy=false,gamesTerm="",gamesDebounce=null,gamesRequestId=0,sbGamesLastRefresh=0;
const GAMES_PAGE_SIZE=50;
const steamProxy="https://proxy.cors.dev/";
async function steamFetchUrl(url){let last;for(const target of [steamProxy+url,url]){const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),12000);try{const response=await fetch(target,{credentials:"omit",headers:{"Accept":"application/json"},signal:ctl.signal});if(!response.ok)throw Error("Steam HTTP "+response.status);const data=await response.json();if(!data||typeof data!=="object"||data.success===false)throw Error("Invalid Steam response");return data}catch(e){last=e}finally{clearTimeout(timer)}}throw last||Error("Steam unavailable")}
function sbSelectedTag(kind){return document.getElementById("sb-genre-"+kind)?.value||""}
function steamSearchUrl(term,start){const u=new URL("https://store.steampowered.com/search/results/");u.searchParams.set("term",term);u.searchParams.set("query",term);u.searchParams.set("start",String(start));u.searchParams.set("count",String(GAMES_PAGE_SIZE));u.searchParams.set("category1","998");u.searchParams.set("infinite","1");u.searchParams.set("ignore_preferences","1");u.searchParams.set("json","1");u.searchParams.set("cc","sa");u.searchParams.set("l",lang==="en"?"english":"arabic");const tag=sbSelectedTag("games");if(tag)u.searchParams.set("tags",tag);return u.toString()}
function sbReleaseDate(raw){
 const v=String(raw||"").trim(),months=["jan","feb","mar","apr","may","jun","jul","aug","sep","oct","nov","dec"];
 let y,m,d,hit=v.match(/^(\d{4})-(\d{2})-(\d{2})$/);
 if(hit){y=+hit[1];m=+hit[2];d=+hit[3]}
 else if(hit=v.match(/^([A-Za-z]+)\s+(\d{1,2}),?\s+(\d{4})$/)){m=months.indexOf(hit[1].slice(0,3).toLowerCase())+1;d=+hit[2];y=+hit[3]}
 else if(hit=v.match(/^(\d{1,2})\s+([A-Za-z]+),?\s+(\d{4})$/)){d=+hit[1];m=months.indexOf(hit[2].slice(0,3).toLowerCase())+1;y=+hit[3]}
 else return "";
 if(y<2000||y>2100||m<1||m>12||d<1||d>31)return "";const dt=new Date(Date.UTC(y,m-1,d));return dt.getUTCFullYear()===y&&dt.getUTCMonth()===m-1&&dt.getUTCDate()===d?dt.toISOString().slice(0,10):"";
}
function sbSarPrice(minor){return minor==null||minor===""||!Number.isFinite(Number(minor))||Number(minor)<0?"":new Intl.NumberFormat(lang==="en"?"en-SA":"ar-SA",{style:"currency",currency:"SAR"}).format(Number(minor)/100)}
