function parseSteamRows(data){const html=data?.results_html||data?.resultsHtml||"";if(!html)return[];const doc=new DOMParser().parseFromString(sbTrusted.html(html),"text/html");return [...doc.querySelectorAll("a.search_result_row")].map(a=>{const id=Number((a.getAttribute("data-ds-appid")||"").split(",")[0]);const name=a.querySelector(".title")?.textContent?.trim();const img=a.querySelector(".search_capsule img")?.getAttribute("src")||a.querySelector("img")?.getAttribute("src")||"";const p=a.querySelector(".discount_final_price,.search_price");const raw=p?.textContent?.trim()||"";const priceType=/free|مجاني/i.test(raw)?"free":/\d/.test(raw)?"paid":"unknown";const releaseRaw=a.querySelector(".search_released")?.textContent?.trim()||"";const finalText=a.querySelector(".discount_final_price")?.textContent?.trim()||"",originalText=a.querySelector(".discount_original_price")?.textContent?.trim()||"",discountText=a.querySelector(".discount_pct")?.textContent||"",percent=Number(discountText.match(/\d+/)?.[0]||0),minor=a.getAttribute("data-price-final"),sar=/SAR|ر\.?\s*س|ريال|SR\b/i.test(finalText);return{id,name,img,priceType,releaseRaw,releaseDate:sbReleaseDate(releaseRaw),discount_percent:percent,original_price:originalText,final_price:finalText,final_price_minor:sar&&minor!==null&&/^\d+$/.test(minor)?Number(minor):null}}).filter(x=>x.id&&x.name)}
function gameCard(x){const d=document.createElement("article");d.className="card vis game-card";d.dataset.priceType=x.priceType||"unknown";d.dataset.sbSteamId=String(x.id);const image=x.img?`<img class="gimg" src="${escapeHtml(sbSafeHttp(x.img))}" alt="${escapeHtml(x.name)}" loading="lazy" data-sb-image-fallback="hide">`:"";sbHtmlTarget(d).html=`${image}<div class="game-content"><h3>${escapeHtml(x.name)}</h3><div class="tag" style="color:var(--m);font-size:.75rem">Steam App ID: ${x.id}</div><div class="game-links"><a class="steam-link" href="https://store.steampowered.com/app/${x.id}/" target="_blank" rel="noopener">🎮 ${tr("steamLink")}</a><a class="db-link" href="https://steamdb.info/app/${x.id}/" target="_blank" rel="noopener">📊 ${tr("steamDB")}</a></div></div>`;return d}
function escapeHtml(v){return String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function setGamesStatus(message){const e=$("gamesStatus");if(e)e.textContent=message}
async function loadGames(reset=false){if(gamesBusy&&!reset)return;let requestId=gamesRequestId;if(reset){requestId=++gamesRequestId;gamesStart=0;gamesTotal=0;gamesTerm=$("gameSearch").value.trim()}gamesBusy=true;setGamesStatus(lang==="en"?"Refreshing live Steam catalog…":"جارٍ تحديث مكتبة Steam مباشرة…");$("gamesMore").disabled=true;
try{const data=await steamFetchUrl(steamSearchUrl(gamesTerm,gamesStart));if(requestId!==gamesRequestId)return;if(data?.success===false)throw new Error("Steam returned an error");let rows=parseSteamRows(data);gamesTotal=Number(data.total_count||gamesTotal||rows.length);if(rows.length===0&&gamesTerm&&!sbSelectedTag("games")){const fallback=await steamFetchUrl(`https://store.steampowered.com/api/storesearch/?term=${encodeURIComponent(gamesTerm)}&l=${lang==="en"?"english":"arabic"}&cc=sa`);if(requestId!==gamesRequestId)return;rows=(fallback.items||[]).filter(x=>x.type==="app").map(x=>({id:x.id,name:x.name,img:x.tiny_image}));gamesTotal=rows.length}if(reset&&rows.length===0){sbGamesLastRefresh=Date.now();sbHtmlTarget($("gameGrid")).html="";$("gamesMore").hidden=true;setGamesStatus(tr("gamesEmpty"));return}const frag=document.createDocumentFragment();rows.forEach(x=>frag.appendChild(gameCard(x)));if(reset){sbHtmlTarget($("gameGrid")).html="";gamesStart=0}$("gameGrid").appendChild(frag);gamesStart+=rows.length;sbGamesLastRefresh=Date.now();const stamp=new Date().toLocaleTimeString(lang==="en"?"en-US":"ar-SA",{hour:"2-digit",minute:"2-digit"});setGamesStatus(`${gamesStart.toLocaleString()} / ${gamesTotal.toLocaleString()} ${tr("gamesCount")} · ${lang==="en"?"Updated":"آخر تحديث"}: ${stamp} · ${lang==="en"?"Auto-refresh every 5 minutes":"تحديث تلقائي كل 5 دقائق"}`);$("gamesMore").hidden=rows.length<GAMES_PAGE_SIZE||gamesStart>=gamesTotal;
}catch(e){if(requestId===gamesRequestId){setGamesStatus(lang==="en"?"Steam could not be reached. Existing results are kept; retrying automatically.":"تعذر الاتصال بمتجر Steam. أبقينا النتائج الحالية وسنعيد المحاولة تلقائياً.");$("gamesMore").hidden=false}}
finally{if(requestId===gamesRequestId){gamesBusy=false;$("gamesMore").disabled=false}}}
function initGamesSearch(){const input=$("gameSearch"),btn=$("gameSearchBtn"),more=$("gamesMore");if(!input||input.dataset.ready)return;input.dataset.ready="1";btn.addEventListener("click",()=>loadGames(true));input.addEventListener("keydown",e=>{if(e.key==="Enter")loadGames(true)});input.addEventListener("input",()=>{clearTimeout(gamesDebounce);gamesDebounce=setTimeout(()=>loadGames(true),450)});more.addEventListener("click",()=>loadGames(false));}
let gLoaded=false;
function loadGamesOnOpen(){initGamesSearch();if(!gLoaded){gLoaded=true;loadGames(true)}}
// Keep the visible Steam library fresh while the page is open. Refreshes pause in background tabs.
setInterval(()=>{const gamesPage=$("games");if(gamesPage?.classList.contains("show")&&!document.hidden&&!gamesBusy&&gamesStart<=GAMES_PAGE_SIZE&&document.activeElement!==$("gameSearch")){loadGames(true)}},5*60*1000);
