const sbSteamCachePrefix="sb_steam_v6_",sbSteamCacheMaxAge=24*60*60*1000;
function sbCacheKey(kind,tag,language){return sbSteamCachePrefix+kind+"_"+tag+"_"+language}
function sbValidSteamRow(x){return x&&Number.isSafeInteger(Number(x.id))&&Number(x.id)>0&&typeof x.name==="string"&&x.name.length>0}
function sbReadSteamCache(kind,tag,language){try{const c=JSON.parse(sessionStorage.getItem(sbCacheKey(kind,tag,language))||"null");if(c&&Number.isFinite(c.at)&&Date.now()-c.at>=0&&Date.now()-c.at<sbSteamCacheMaxAge&&Array.isArray(c.rows)&&c.rows.every(sbValidSteamRow))return c}catch(e){}return null}
function sbWriteSteamCache(kind,tag,language,rows){try{sessionStorage.setItem(sbCacheKey(kind,tag,language),JSON.stringify({at:Date.now(),rows:rows.filter(sbValidSteamRow).slice(0,36)}))}catch(e){}}
function sbSteamStamp(at){return new Date(at).toLocaleString(lang==="en"?"en-GB":"ar-SA-u-ca-gregory",{dateStyle:"short",timeStyle:"short"})}
const steamCollections={free:{loaded:false,busy:false},deals:{loaded:false,busy:false},upcoming:{loaded:false,busy:false}};
function steamCollectionSearch(kind){const u=new URL("https://store.steampowered.com/search/results/");u.searchParams.set("query","");u.searchParams.set("start","0");u.searchParams.set("count","36");u.searchParams.set("category1","998");u.searchParams.set("infinite","1");u.searchParams.set("ignore_preferences","1");u.searchParams.set("json","1");u.searchParams.set("cc","sa");u.searchParams.set("l",lang==="en"?"english":"arabic");const tag=sbSelectedTag(kind);if(tag)u.searchParams.set("tags",tag);if(kind==="deals")u.searchParams.set("specials","1");if(kind==="free")u.searchParams.set("maxprice","free");if(kind==="upcoming"){u.searchParams.set("filter","comingsoon");u.searchParams.set("l","english");}return u.toString()}
function steamCollectionCard(x,kind){const d=document.createElement("article");d.className="card collection-card vis";d.dataset.sbSteamId=String(x.id);if(kind==="upcoming"){d.dataset.sbRelease=x.releaseDate||"";d.dataset.sbReleaseRaw=x.releaseRaw||"";}if(kind==="deals"){d.dataset.discount=String(x.discount_percent||0);d.dataset.price=x.final_price_minor==null?"":String(x.final_price_minor/100);}const img=x.img?`<img class="gimg" src="${escapeHtml(sbSafeHttp(x.img))}" alt="${escapeHtml(x.name)}" loading="lazy" data-sb-image-fallback="hide">`:"";let price="";if(kind==="deals"){const missing=lang==="en"?"Unavailable":"غير متاح";price=`<div class="sb-deal-values"><span>${lang==="en"?"Before":"قبل الخصم"} <s class="muted-price">${escapeHtml(x.original_price||missing)}</s></span><span>${lang==="en"?"After":"بعد الخصم"} <strong class="current-price">${escapeHtml(x.final_price||missing)}</strong></span><span>${lang==="en"?"Discount":"نسبة الخصم"} <b class="discount">${Number(x.discount_percent||0)}%</b></span></div>`;}if(kind==="upcoming"){const validRelease=typeof x.releaseDate==="string"&&/^\d{4}-\d{2}-\d{2}$/.test(x.releaseDate)&&Number.isFinite(Date.parse(x.releaseDate+"T00:00:00Z"));const date=validRelease?new Intl.DateTimeFormat(lang==="en"?"en-GB":"ar-SA-u-ca-gregory",{dateStyle:"medium",timeZone:"UTC"}).format(new Date(x.releaseDate+"T00:00:00Z")):x.releaseRaw||(lang==="en"?"Not announced":"لم يحدد بعد");price=`<p class="note" style="margin:10px 0">${lang==="en"?"Release date":"موعد الإصدار"}: ${escapeHtml(date)}</p>`;}const tag=kind==="free"?(lang==="en"?"Free to play":"مجانية للعب"):kind==="upcoming"?(lang==="en"?"Coming soon":"قريبًا"):"";sbHtmlTarget(d).html=`${img}<div class="ctop"><div class="ctitle"><h3>${escapeHtml(x.name||"")}</h3></div></div>${tag?`<div class="tag">${tag}</div>`:""}${price}<div class="cacts"><a class="btn btn-p" href="https://store.steampowered.com/app/${Number(x.id)}/" target="_blank" rel="noopener">🎮 ${lang==="en"?"Steam Store":"متجر Steam"}</a><a class="btn btn-g" href="https://steamdb.info/app/${Number(x.id)}/" target="_blank" rel="noopener">SteamDB</a></div>`;return d}
function steamCollectionStatus(kind,msg){const e=$(kind+"Status");if(e)e.textContent=msg}
async function loadSteamCollection(kind,force=false){const state=steamCollections[kind];if(!state||(!force&&state.busy)||(!force&&state.loaded&&state.shownTag===sbSelectedTag(kind)&&state.shownLanguage===lang&&Date.now()-(state.updatedAt||0)<5*60*1000))return;const requestId=(state.requestId||0)+1;state.requestId=requestId;state.busy=true;const grid=$(kind+"Grid"),tag=sbSelectedTag(kind),language=lang;const cached=sbReadSteamCache(kind,tag,language);if(cached&&(!grid.querySelector(".collection-card")||state.shownTag!==tag||state.shownLanguage!==language)){grid.replaceChildren(...cached.rows.map(v=>steamCollectionCard(v,kind)));state.shownTag=tag;state.shownLanguage=language;}steamCollectionStatus(kind,lang==="en"?"Loading live Steam data…":"جارٍ تحميل بيانات Steam المباشرة…");try{let rows=[];if(kind==="deals"&&!tag){const data=await steamFetchUrl("https://store.steampowered.com/api/featuredcategories/?cc=sa&l="+(lang==="en"?"english":"arabic"));if(!Array.isArray(data?.specials?.items))throw Error("Missing Steam deals");rows=data.specials.items.filter(v=>Number(v.discount_percent)>0).map(sbSteamDeal);}else{const data=await steamFetchUrl(steamCollectionSearch(kind));if(data?.success===false||typeof (data?.results_html??data?.resultsHtml)!=="string")throw Error("Steam returned an incomplete search");rows=parseSteamRows(data);if(kind==="deals")rows=rows.filter(x=>x.discount_percent>0);}if(requestId!==state.requestId||sbSelectedTag(kind)!==tag||lang!==language)return;if(!rows.length){grid.replaceChildren();state.loaded=true;state.shownTag=tag;state.shownLanguage=language;state.updatedAt=Date.now();sbWriteSteamCache(kind,tag,language,[]);steamCollectionStatus(kind,lang==="en"?"No matching games":"لا توجد ألعاب مطابقة");return;}if(kind==="upcoming")rows.sort((a,b)=>(a.releaseDate||"9999").localeCompare(b.releaseDate||"9999"));sbHtmlTarget(grid).html="";rows.slice(0,36).forEach(v=>grid.appendChild(steamCollectionCard(v,kind)));state.loaded=true;state.shownTag=tag;state.shownLanguage=language;state.updatedAt=Date.now();sbWriteSteamCache(kind,tag,language,rows);steamCollectionStatus(kind,`${Math.min(rows.length,36)} ${lang==="en"?"games · Updated":"لعبة · آخر تحديث"} ${new Date().toLocaleTimeString(lang==="en"?"en-US":"ar-SA",{hour:"2-digit",minute:"2-digit"})}`);}catch(err){if(requestId!==state.requestId)return;steamCollectionStatus(kind,lang==="en"?"Steam data is temporarily unavailable. Open the official Steam page instead.":"تعذر جلب بيانات Steam مؤقتًا. يمكنك فتح صفحة Steam الرسمية أدناه.");if(grid.querySelector(".collection-card")){const at=state.shownTag===tag&&state.shownLanguage===language?(cached?.at||state.updatedAt):null;steamCollectionStatus(kind,(lang==="en"?"Refresh failed · cached data, prices may have changed":"تعذر التحديث · بيانات محفوظة وقد تكون الأسعار تغيرت")+(at?" · "+sbSteamStamp(at):""));}if(!grid.children.length){const destinations={free:["https://store.steampowered.com/genre/Free%20to%20Play/","Steam Free to Play"],deals:["https://store.steampowered.com/specials/","Steam Specials"],upcoming:["https://store.steampowered.com/search/?filter=comingsoon","Steam Upcoming"]};const box=document.createElement("div");box.className="collection-empty";const a=document.createElement("a");a.className="btn btn-red";a.href=destinations[kind][0];a.target="_blank";a.rel="noopener";a.textContent=destinations[kind][1];box.appendChild(a);grid.appendChild(box);}}finally{if(requestId===state.requestId)state.busy=false}}
