 async function loadAdminGames(){await requireAdmin();const {data,error}=await window.sbSupabase.from("games").select("*").order("created_at",{ascending:false});if(error)throw error;adminGames=data||[];return adminGames;}
 function renderAdminGames(){const host=$a("sb-games-table");$a("sb-games-count").textContent=fmtN(adminGames.length);const q=$a("sb-p7-game-search").value.trim().toLocaleLowerCase(),f=$a("sb-p7-game-filter").value;const visible=adminGames.filter(g=>(f==="all"||g.status===f)&&(!q||[g.name,g.platform,g.category,g.description].some(x=>String(x||"").toLocaleLowerCase().includes(q))));$a("sb-p7-game-result").textContent="عرض "+fmtN(visible.length)+" من "+fmtN(adminGames.length);if(!adminGames.length){sbHtmlTarget(host).html='<div class="sb-empty">لا توجد ألعاب محفوظة بعد.</div>';return;}if(!visible.length){host.textContent="لا توجد ألعاب تطابق الفلتر.";return;}sbHtmlTarget(host).html='<table><thead><tr><th>اللعبة</th><th>المنصة</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody>'+visible.map(g=>'<tr><td><div class="sb-item-cell">'+(g.image_url?'<img class="sb-item-thumb" src="'+esc(sbSafeHttp(g.image_url))+'" alt="">':'<span class="sb-item-thumb sb-item-thumb-empty">🎮</span>')+'<div><b>'+esc(g.name)+'</b><div class="sb-muted">'+esc(g.description||"")+'</div></div></div></td><td>'+esc(g.platform||"غير محدد")+'</td><td>'+(g.status==="published"?"منشورة":"مسودة")+'</td><td><div class="sb-item-actions"><button class="sb-btn" data-game-edit="'+esc(g.id)+'">تعديل</button><button class="sb-btn danger" data-game-delete="'+esc(g.id)+'">حذف</button></div></td></tr>').join("")+'</tbody></table>';host.querySelectorAll("[data-game-edit]").forEach(b=>b.onclick=()=>editGame(b.dataset.gameEdit));host.querySelectorAll("[data-game-delete]").forEach(b=>b.onclick=()=>deleteGame(b.dataset.gameDelete));}
 let currentGameImageUrl=null,gameImagePreviewObjectUrl=null;
 function clearGameImage(){if(gameImagePreviewObjectUrl){URL.revokeObjectURL(gameImagePreviewObjectUrl);gameImagePreviewObjectUrl=null;}$a("sb-game-image-preview").removeAttribute("src");$a("sb-game-image-preview-wrap").hidden=true;$a("sb-game-image").value="";}
 $a("sb-game-image").addEventListener("change",()=>{const file=$a("sb-game-image").files?.[0];if(!file)return;if(!["image/jpeg","image/png","image/webp","image/gif"].includes(file.type)||file.size>5*1024*1024){$a("sb-game-status-message").textContent="صيغة الصورة أو حجمها غير مقبول.";$a("sb-game-image").value="";return;}if(gameImagePreviewObjectUrl)URL.revokeObjectURL(gameImagePreviewObjectUrl);gameImagePreviewObjectUrl=URL.createObjectURL(file);$a("sb-game-image-preview").src=gameImagePreviewObjectUrl;$a("sb-game-image-preview-wrap").hidden=false;});
