 function renderStats(){
  const since=new Date();since.setHours(0,0,0,0);since.setDate(since.getDate()-statsRange+1);
  const periodEvents=cloudEvents.filter(e=>new Date(e.created_at)>=since);
  const items=readItems(), byId=new Map(items.map(x=>[String(x.id),x.n])), grouped=Object.create(null);
  adminGames.forEach(x=>byId.set(String(x.id),x.name));
  periodEvents.forEach(e=>{const id=String(e.item_key||"site");if(!grouped[id])grouped[id]={views:0,downs:0};if(e.event_type==="view")grouped[id].views++;if(e.event_type==="download")grouped[id].downs++;});
  const rows=Object.entries(grouped).map(([id,v])=>({id,name:byId.get(id)||id,views:v.views,downs:v.downs,total:v.views+v.downs})).filter(x=>x.total>0).sort((a,b)=>b.total-a.total);
  reportRows=rows;
  if(cloudLoadedAt&&!$a("sb-p7-csv").disabled){const incomplete=cloudCount===null||cloudCount>cloudEvents.length; $a("sb-p7-scope").textContent="آخر تحميل: "+cloudLoadedAt.toLocaleString("ar-SA")+" | "+fmtN(periodEvents.length)+" حدث خلال "+statsRange+" أيام"+(incomplete?" | النتائج قد تكون جزئية (أحدث "+fmtN(cloudEvents.length)+" حدث محمّل).":" | جميع الأحداث المتاحة عند التحميل.");}
  const topHost=$a("sb-top-items");
  sbHtmlTarget(topHost).html=rows.length?'<div class="sb-top-list">'+rows.slice(0,5).map((x,i)=>'<div class="sb-top-item"><span class="sb-top-rank">'+(i+1)+'</span><div><div class="sb-top-name">'+esc(x.name)+'</div><div class="sb-top-meta">'+fmtN(x.views)+' مشاهدة · '+fmtN(x.downs)+' نقرة</div></div><strong class="sb-top-total">'+fmtN(x.total)+'</strong></div>').join("")+'</div>':'<div class="sb-empty">لا توجد تفاعلات كافية لعرض ترتيب العناصر بعد.</div>';
  sbHtmlTarget($a("sb-stats-table")).html=`<table><thead><tr><th>العنصر</th><th>مشاهدات التفاصيل</th><th>نقرات الروابط</th></tr></thead><tbody>${rows.slice(0,100).map(x=>`<tr><td>${esc(x.name)}</td><td>${fmtN(x.views)}</td><td>${fmtN(x.downs)}</td></tr>`).join("")}</tbody></table>`;
  const totals=cloudTotals(periodEvents);
  $a("sb-analytics-visits").textContent=fmtN(totals.visits);sbRenderCountries(periodEvents,"sb-country-kpi","sb-country-list");
  $a("sb-analytics-views").textContent=fmtN(totals.views);
  $a("sb-analytics-clicks").textContent=fmtN(totals.downloads);
  const today=new Date();today.setHours(0,0,0,0);
  const days=Array.from({length:statsRange},(_,i)=>{const d=new Date(today);d.setDate(today.getDate()-statsRange+1+i);return {date:d,count:0};});
  const dayMap=new Map(days.map(d=>[d.date.toDateString(),d]));
  periodEvents.forEach(e=>{const d=new Date(e.created_at);if(Number.isNaN(d.getTime()))return;d.setHours(0,0,0,0);const slot=dayMap.get(d.toDateString());if(slot)slot.count++;});
  const max=Math.max(1,...days.map(d=>d.count));
  sbHtmlTarget($a("sb-activity-chart")).html=days.map(d=>{const h=d.count?Math.max(5,Math.round(d.count/max*100)):2;const label=statsRange===7?d.date.toLocaleDateString("ar-SA",{weekday:"short"}):d.date.toLocaleDateString("ar-SA",{day:"numeric",month:"numeric"});return `<div class="sb-chart-day" title="${d.date.toLocaleDateString("ar-SA")}: ${fmtN(d.count)} حدث"><span class="sb-chart-value">${fmtN(d.count)}</span><div class="sb-chart-bar" style="height:${h}%"></div><span class="sb-chart-label">${label}</span></div>`;}).join("");
  document.querySelectorAll("[data-stats-range]").forEach(b=>b.classList.toggle("active",Number(b.dataset.statsRange)===statsRange));
 }
