 async function renderPublicGames(){const wrap=$a("sb-curated-games-wrap"),host=$a("sb-curated-game-grid");if(!wrap||!host||sbCuratedBusy)return;sbCuratedBusy=true;try{await sbLoadSdk();const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),15000);let result;try{result=await window.sbSupabase.from("games").select("id,name,description,category,image_url,platform,official_url").eq("status","published").order("created_at",{ascending:false}).abortSignal(ctl.signal)}finally{clearTimeout(timer)}const {data,error}=result;if(error||!Array.isArray(data))throw error||Error("Incomplete games catalog");sbCuratedAt=Date.now();window.sbContentStatus?.("games",true,sbCuratedAt);const signature=JSON.stringify(data);if(signature===sbCuratedSignature)return;sbHtmlTarget(host).html="";(data||[]).forEach(g=>{const card=document.createElement("article");card.className="card";card.dataset.sbCategory=g.category||"";card.dataset.sbPlatform=g.platform||"";const safeUrl=sbSafeHttp(g.official_url);sbHtmlTarget(card).html=(g.image_url?'<img class="gimg" src="'+escapeHtml(sbSafeHttp(g.image_url))+'" alt="'+escapeHtml(g.name)+'" loading="lazy">':'')+'<div class="ctop"><div class="ico">🎮</div><div class="ctitle"><h3>'+escapeHtml(g.name)+'</h3></div></div><p class="cdesc">'+escapeHtml(g.description||"")+'</p><div class="sb-muted">'+escapeHtml([g.category,g.platform].filter(Boolean).join(" · "))+'</div><div class="cacts"><a class="btn btn-p" href="'+escapeHtml(safeUrl)+'" target="_blank" rel="noopener" data-game-open="'+escapeHtml(g.id)+'" style="flex:1">عرض اللعبة ↗</a></div>';host.appendChild(card);});wrap.hidden=!(data||[]).length;host.querySelectorAll("[data-game-open]").forEach(a=>a.addEventListener("click",()=>window.sbTrackEvent("download",a.dataset.gameOpen)));sbCuratedSignature=signature;}catch(err){window.sbContentStatus?.("games",false,sbCuratedAt);console.warn("SAUDI BYTE curated games unavailable:",err.message||err);}finally{sbCuratedBusy=false}}
