const browseQuery="query { trending: Page(page:1,perPage:24){ media(type:ANIME,sort:TRENDING_DESC,isAdult:false){ "+fields+" } } popular: Page(page:1,perPage:24){ media(type:ANIME,sort:POPULARITY_DESC,isAdult:false){ "+fields+" } } newest: Page(page:1,perPage:18){ media(type:ANIME,sort:START_DATE_DESC,isAdult:false,format_in:[TV,MOVIE]){ "+fields+" } } }";
const searchQuery="query ($search:String!){ Page(page:1,perPage:18){ media(search:$search,type:ANIME,isAdult:false,sort:SEARCH_MATCH){ "+fields+" } } }";
let animeItems=[],animeType="all",animeGenre="all",searchTimer=null,searchCache=new Map(),lastSync=0,isLoading=false,currentSearchItems=null;
const $=id=>document.getElementById(id),isEnglish=()=>document.documentElement.lang==="en";
const safe=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
