const status=message=>{const el=$("saAnimeStatus");if(el)el.textContent=message};
async function request(query,variables={}){const response=await fetch(API,{method:"POST",headers:{"Content-Type":"application/json","Accept":"application/json"},body:JSON.stringify({query,variables})});if(!response.ok)throw new Error("AniList API "+response.status);const json=await response.json();if(json.errors?.length)throw new Error(json.errors[0].message||"GraphQL error");return json.data}
