function persist(){try{localStorage.setItem(CACHE_KEY,JSON.stringify({savedAt:Date.now(),items:animeItems}))}catch(e){}}
function loadCache(){try{const c=JSON.parse(localStorage.getItem(CACHE_KEY)||"null");if(c?.items?.length){animeItems=c.items.map(shape);lastSync=c.items.some(x=>x.coverImage?.extraLarge||x.coverImage?.medium)?c.savedAt||0:0;return true}}catch(e){}return false}
async function syncCatalog(force=false){if(isLoading)return;if(!force&&animeItems.length&&Date.now()-lastSync<CACHE_TTL)return;isLoading=true;status(isEnglish()?"Updating anime catalog…":"يتم تحديث مكتبة الأنمي تلقائيًا…");try{const data=await request(browseQuery);const next=unique([...(data.trending?.media||[]),...(data.popular?.media||[]),...(data.newest?.media||[])]);if(!next.length)throw Error("Empty AniList catalog");animeItems=next;lastSync=Date.now();persist();render();status(isEnglish()?"Catalog updated from AniList · refreshes every 6 hours":"تم تحديث المكتبة من AniList · تتجدد تلقائيًا كل 6 ساعات")}catch(error){status(animeItems.length?(isEnglish()?"Showing saved catalog · automatic refresh will retry":"نعرض آخر نسخة محفوظة · سيُعاد التحديث تلقائيًا"):(isEnglish()?"Could not load the live catalog right now.":"تعذر تحميل المكتبة المباشرة حاليًا."));console.warn("SAUDI ANIME sync failed:",error)}finally{isLoading=false}}
window.saAnimeSearchChanged=()=>{clearTimeout(searchTimer);const q=$("saAnimeSearch")?.value.trim()||"";if(!q){currentSearchItems=null;render();return}searchTimer=setTimeout(async()=>{if(searchCache.has(q)){currentSearchItems=searchCache.get(q);render();return}status(isEnglish()?"Searching English and Japanese titles…":"جاري البحث بالاسم الإنجليزي والياباني…");try{const data=await request(searchQuery,{search:q});currentSearchItems=(data.Page?.media||[]).map(shape);searchCache.set(q,currentSearchItems);render();status(isEnglish()?"Search results from AniList":"نتائج البحث من AniList")}catch(e){currentSearchItems=animeItems.filter(x=>(titleOf(x)+" "+nativeOf(x)+" "+(x.title?.romaji||"")).toLowerCase().includes(q.toLowerCase()));render();status(isEnglish()?"Showing matches from the loaded catalog":"نعرض النتائج الموجودة في المكتبة المحمّلة")}},420)};
window.saAnimeSetType=(type,button)=>{animeType=type;document.querySelectorAll("[data-anime-type]").forEach(x=>x.classList.toggle("active",x===button));render()};
