window.saAnimeRender=()=>render();
function posterCandidates(cover){return [...new Set([cover?.extraLarge,cover?.large,cover?.medium].filter(v=>typeof v==="string"&&/^https:\/\/[a-z0-9.-]+(?::443)?\/[^\s<>"']+$/i.test(v)))]}
function loadPoster(img,item,index){const choices=posterCandidates(item?.coverImage),root=img.parentElement;let next=0;img.loading=index<8?"eager":"lazy";const fail=()=>{if(next<choices.length){img.src=choices[next++];return}img.hidden=true;root.dataset.coverState="missing";root.querySelector(".sa-anime-cover-fallback").textContent=isEnglish()?"Poster unavailable":"الصورة غير متاحة"};img.addEventListener("load",()=>{root.dataset.coverState="ready";img.hidden=false});img.addEventListener("error",fail);fail()}

function render(){const host=$("saAnimeGrid");if(!host||!$("anime")?.classList.contains("show"))return;const q=($("saAnimeSearch")?.value||"").trim().toLowerCase(),source=currentSearchItems!==null?currentSearchItems:animeItems;const sbStatus=$("sbAnimeStatus")?.value||"all",sbScore=$("sbAnimeScore")?.value||"all";const rows=source.filter(x=>(sbStatus==="all"||x.status===sbStatus)&&(sbScore==="all"||(x.averageScore!=null&&x.averageScore>=Number(sbScore)))&&(animeType==="all"||x.kind===animeType)&&(animeGenre==="all"||(x.genreList||[]).includes(animeGenre))&&(!q||(titleOf(x)+" "+nativeOf(x)+" "+(x.title?.romaji||"")).toLowerCase().includes(q)));sbHtmlTarget(host).html=rows.map(x=>{const en=titleOf(x),jp=nativeOf(x),genres=(x.genreList||[]).slice(0,3);return '<article class="sa-anime-card"><div class="sa-anime-poster"><span class="sa-anime-cover-fallback" aria-hidden="true">アニメ</span><img class="sa-anime-cover" alt="'+safe(en)+'" decoding="async" referrerpolicy="no-referrer"><span class="sa-anime-badge">'+(x.kind==="movie"?(isEnglish()?"MOVIE":"فيلم"):(isEnglish()?"SERIES":"مسلسل"))+'</span><span class="sa-anime-rating">'+(x.averageScore?"★ "+(x.averageScore/10).toFixed(1):"")+'</span><strong>'+safe(en)+'</strong></div><div class="sa-anime-card-body"><h3 lang="en" dir="ltr">'+safe(en)+'</h3><div class="sa-anime-japanese" lang="ja" dir="ltr">'+safe(jp)+'</div><div class="sa-anime-meta"><span>'+safe(yearOf(x))+'</span><span>'+safe(x.format||"ANIME")+'</span></div><div class="sa-anime-tags">'+genres.map(g=>'<span>'+safe(g)+'</span>').join("")+'</div></div><button class="sa-anime-details" data-sb-anime-open="'+Number(x.id)+'">'+(isEnglish()?"Details & AniList ↗":"التفاصيل وAniList ↗")+'</button></article>'}).join("");host.querySelectorAll(".sa-anime-cover").forEach((img,i)=>loadPoster(img,rows[i],i));$("saAnimeEmpty").style.display=rows.length?"none":"block"}
window.saAnimeOpen=id=>{const x=animeItems.find(a=>a.id===id)||currentSearchItems?.find(a=>a.id===id);if(!x)return;let modal=$("saAnimeModal");if(!modal){modal=document.createElement("div");modal.id="saAnimeModal";modal.className="sa-anime-modal";sbHtmlTarget(modal).html='<div class="sa-anime-modal-box"><button class="sa-anime-modal-close" data-sb-anime-close>✕</button><div class="section-kicker">SAUDI ANIME / ANILIST</div><h3 id="saAnimeModalTitle"></h3><div id="saAnimeModalNative" class="sa-anime-japanese" dir="ltr" lang="ja"></div><p id="saAnimeModalDesc"></p><a id="saAnimeModalLink" target="_blank" rel="noopener" style="color:#ff737b;font-size:12px">AniList ↗</a><p style="color:#aaa;margin-top:14px">روابط المشاهدة الرسمية ستُضاف فقط بعد التحقق من توفرها.</p></div>';modal.addEventListener("click",e=>{if(e.target===modal)modal.classList.remove("show")});document.body.appendChild(modal)}$("saAnimeModalTitle").textContent=titleOf(x);$("saAnimeModalNative").textContent=nativeOf(x);$("saAnimeModalDesc").textContent=(x.description||"").replace(/<[^>]*>/g," ").slice(0,500)||"No synopsis available.";const animeUrl=sbSafeHttp(x.siteUrl);$("saAnimeModalLink").href=animeUrl==="#"?"https://anilist.co":animeUrl;modal.classList.add("show")};
if(loadCache()){render();status(isEnglish()?"Showing saved catalog · checking for updates":"نعرض المكتبة المحفوظة · نتحقق من وجود تحديثات")}else status(isEnglish()?"Loading live anime catalog…":"جاري تحميل مكتبة الأنمي المباشرة…");
