 function fill(el,items){const options=[["all","الكل","All"],...items];const sig=JSON.stringify(options)+en();if(el.dataset.sig===sig)return;const prev=el.value;el.dataset.sig=sig;el.replaceChildren(...options.map(([v,a,e])=>{const o=document.createElement("option");o.value=v;o.textContent=t(a,e);return o}));el.value=options.some(x=>x[0]===prev)?prev:"all"}
