 for(const c of cards){const ok=(!term||names(c).toLocaleLowerCase().includes(term))&&controls.every(({el,d})=>el.value==="all"||d.get(c)===el.value);c.dataset.sbFiltered=ok?"0":"1";if(ok&&!c.hidden)n++}
 if(order){for(const c of cards)c.style.order="";if(order.value!=="all")cards.slice().sort((a,b)=>names(a).localeCompare(names(b),undefined,{numeric:true})*(order.value==="za"?-1:1)).forEach((c,i)=>c.style.order=String(i+1))}
 if(headers)for(const h of host.querySelectorAll(".section-kicker")){let p=h.nextElementSibling,ok=false;while(p&&!p.classList.contains("section-kicker")){if(p.matches(".tv-channel")&&p.dataset.sbFiltered!=="1")ok=true;p=p.nextElementSibling}h.dataset.sbFiltered=ok?"0":"1"}
